lab.inicial:
-- Lab: write whatever you want. Everything runs on a fresh Postgres at every change.
-- auth.users, auth.uid() and auth.jwt() work as they do in Supabase.

insert into auth.users (id, email) values
  ('11111111-1111-4111-8111-111111111111', 'ana@example.com'),
  ('22222222-2222-4222-8222-222222222222', 'beto@example.com');

create table public.notes (
  id        int primary key,
  user_id   uuid references auth.users (id),
  body      text,
  is_public boolean not null default false
);

insert into public.notes values
  (1, '11111111-1111-4111-8111-111111111111', 'shopping list', false),
  (2, '11111111-1111-4111-8111-111111111111', 'cake recipe', true),
  (3, '22222222-2222-4222-8222-222222222222', 'wi-fi password', false);

alter table public.notes enable row level security;

create policy read_notes on public.notes
  for select
  using (is_public or user_id = auth.uid());
